def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    pressure_bids = []
    desperate_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev.get('bid', 0)
                prev_bids.append(bid)
                if opp.get('hp', 10) <= 4 or opp.get('no_water_days', 0) >= 1:
                    pressure_bids.append(bid)

    if not alive_opponents:
        return float(min(budget, DAILY_SALARY * 0.35))

    units = int(supply // WATER_REQ)
    scarcity = 1.0 if units <= 1 else 0.0

    highest_prev = max(prev_bids) if prev_bids else DAILY_SALARY * 0.75
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else DAILY_SALARY * 0.65
    urgent_prev = max(pressure_bids) if pressure_bids else highest_prev

    my_urgent = hp <= 3 or no_water_days >= 2
    my_semi_urgent = hp <= 5 or no_water_days >= 1

    if my_urgent:
        target = max(highest_prev + 2.0, DAILY_SALARY * 1.55)
        if scarcity and desperate_count >= 1:
            target = max(target, DAILY_SALARY * 1.7)
    elif my_semi_urgent:
        target = max(urgent_prev + 1.5, DAILY_SALARY * 1.1)
        if scarcity:
            target = max(target, DAILY_SALARY * 1.25)
    else:
        if scarcity:
            if highest_prev >= 110:
                target = DAILY_SALARY * 0.28
            elif avg_prev >= 80:
                target = DAILY_SALARY * 0.42
            else:
                target = avg_prev + 1.0
        else:
            target = max(DAILY_SALARY * 0.5, avg_prev * 0.8)

    if day >= 8:
        if hp <= 6:
            target = max(target, highest_prev + 1.0)
        else:
            target = max(target, DAILY_SALARY * 0.6)

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = DAILY_SALARY * (8 - day) * 0.15
    max_affordable = max(0.0, budget - reserve_floor)
    if my_urgent:
        max_affordable = budget

    bid = min(target, max_affordable)
    if bid <= 0:
        bid = min(budget, DAILY_SALARY * 0.2)

    if my_urgent and budget > 0:
        bid = max(bid, min(budget, DAILY_SALARY * 0.95))

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Identify alive opponents and read yesterday bids
    alive_opponents = []
    yesterday_bids = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                yesterday_bids.append(float(prev.get('bid')))

    # If no opponents alive, conserve
    if not alive_opponents:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Pressure from yesterday: who was willing to pay the most
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Supply-based aggressiveness: higher supply means we can secure water cheaper
    # Normalize supply in [0,1]
    denom = float(MAX_SUPPLY - MIN_SUPPLY) if (MAX_SUPPLY - MIN_SUPPLY) != 0 else 1.0
    supply_norm = (supply - float(MIN_SUPPLY)) / denom
    if supply_norm < 0.0:
        supply_norm = 0.0
    if supply_norm > 1.0:
        supply_norm = 1.0

    # Base bid target
    # If someone paid extremely high yesterday, match slightly below to avoid overpaying.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        base = DAILY_SALARY * (0.38 + 0.25 * supply_norm)
        # If my hp is critical, bid closer to the top pressure
        if float(my_status['hp']) <= 2:
            base = DAILY_SALARY * (0.75 + 0.15 * supply_norm)
        else:
            base = min(base, highest_prev_bid * 0.92)
    else:
        # Otherwise bid to beat typical mid-pack bids
        base = DAILY_SALARY * (0.48 + 0.22 * supply_norm)

    # Budget and survival constraints
    budget = float(my_status['budget'])
    hp = float(my_status['hp'])
    no_water_days = int(my_status['no_water_days'])

    # If we have gone many days without water, increase urgency
    if no_water_days >= 2 or hp <= 2:
        base *= 1.15

    # If budget is low, cap aggressively
    # Keep some buffer so we don't go to zero too early
    if budget <= DAILY_SALARY * 0.35:
        base = min(base, budget)
    else:
        # Avoid spending everything unless hp is very low
        if hp > 2:
            base = min(base, budget * 0.65)
        else:
            base = min(base, budget * 0.9)

    # Final clamp to [0, budget]
    if base < 0.0:
        base = 0.0
    if base > budget:
        base = budget

    # Ensure at least a small positive bid if possible
    if base == 0.0 and budget > 0.0:
        base = min(budget, DAILY_SALARY * 0.1)

    return float(base)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 1.3
    elif my_status['hp'] <= 4:
        base_bid = DAILY_SALARY * 1.1
    elif my_status['hp'] >= 8:
        base_bid = DAILY_SALARY * 0.7
    else:
        base_bid = DAILY_SALARY * 0.9

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if my_status['hp'] <= 2:
            bid = max(base_bid, highest_prev_bid + 5)
        elif my_status['hp'] <= 4:
            bid = max(base_bid, highest_prev_bid + 2)
        elif my_status['hp'] >= 8:
            bid = min(base_bid, max(DAILY_SALARY * 0.5, highest_prev_bid * 0.9))
        else:
            bid = max(base_bid, highest_prev_bid + 1)
    else:
        bid = base_bid

    if day_context['day'] > EPISODE_DAYS - 3:
        if my_status['hp'] <= 4:
            bid = max(bid, DAILY_SALARY * 1.5)
        else:
            bid = max(bid, DAILY_SALARY * 1.2)

    final_bid = max(1.0, bid)
    final_bid = min(my_status['budget'], final_bid)

    return final_bid
